    return Markup(_escape_inner(str(s)))


def escape(cls, s: t.Any, /) ->te.Self:
    if s is None:
        return cls()
    if hasattr(s, "__html__"):
        return cls(s.__html__())
    return cls(_escape_inner(str(s)))


def __html_format__(self, format_spec: str, /) ->te.Self:
    if format_spec:
